# 운영성(Operability) 예시: Python 3에서 실행 가능한 코드
signals = {"logs": True, "metrics": True, "alerts": True}
print(all(signals.values()))

# 병목 지점(Bottleneck) 예시: Python 3에서 실행 가능한 코드
stages = {"api": 100, "db": 30, "cache": 200}
print(min(stages, key=stages.get))

# 단일 장애점(SPOF) 예시: Python 3에서 실행 가능한 코드
components = {"db_primary": 1, "api": 3}
print([k for k, n in components.items() if n == 1])

# 헬스 체크 예시: Python 3에서 실행 가능한 코드
checks = {"db": True, "disk": True, "queue": False}
print(all(checks.values()))

# 캐싱 전략 예시: Python 3에서 실행 가능한 코드
cache = {}
key = "user:1"
cache[key] = {"name": "Kim"}
print(cache.get(key))

# 캐시 히트/미스 예시: Python 3에서 실행 가능한 코드
cache = {"a": 1}
for key in ["a", "b"]:
    print(key, "hit" if key in cache else "miss")

# 캐시 무효화 예시: Python 3에서 실행 가능한 코드
cache = {"price": 1000}
data_changed = True
if data_changed:
    cache.pop("price", None)
print(cache)

# 라이트 스루 캐시 예시: Python 3에서 실행 가능한 코드
cache = {}; db = {}
def write(k, v):
    cache[k] = v; db[k] = v
write("x", 1)
print(cache, db)

# 라이트 백 캐시 예시: Python 3에서 실행 가능한 코드
cache = {"x": 2}
dirty = {"x"}
db = {}
for k in dirty:
    db[k] = cache[k]
print(db)

# Memcached 예시: Python 3에서 실행 가능한 코드
cache = {"page:/home": "<html>"}
print(cache.get("page:/home"))

# API 설계 원칙 예시: Python 3에서 실행 가능한 코드
response = {"data": {"id": 1}, "error": None}
print(response["data"]["id"])

# 페이로드 크기 최적화 예시: Python 3에서 실행 가능한 코드
user = {"id": 1, "name": "Kim", "bio": "x" * 100}
small = {k: user[k] for k in ["id", "name"]}
print(small)

# Protocol Buffers 예시: Python 3에서 실행 가능한 코드
schema = {"id": "int32", "name": "string"}
message = {"id": 1, "name": "Kim"}
print(all(k in message for k in schema))

# 데이터 파티셔닝 예시: Python 3에서 실행 가능한 코드
users = list(range(8))
parts = {0: [], 1: []}
for u in users:
    parts[u % 2].append(u)
print(parts)

# 멀티 리더 예시: Python 3에서 실행 가능한 코드
writes = {"seoul": {"x": 1}, "tokyo": {"x": 2}}
print(list(writes))

# 벡터 시계 예시: Python 3에서 실행 가능한 코드
a = {"n1": 2, "n2": 1}
b = {"n1": 2, "n2": 3}
print(all(a[k] <= b[k] for k in a))

# etcd 예시: Python 3에서 실행 가능한 코드
store = {"/services/api": "10.0.0.1"}
print(store["/services/api"])

# 서비스 디스커버리 예시: Python 3에서 실행 가능한 코드
registry = {"payments": ["10.0.0.2", "10.0.0.3"]}
print(registry["payments"][0])

# 사이드카 패턴 예시: Python 3에서 실행 가능한 코드
pod = {"app": "api", "sidecar": "proxy"}
print(pod["sidecar"])

# 알림 시스템 설계 예시: Python 3에서 실행 가능한 코드
prefs = {"u1": ["email", "push"]}
event = "sale"
for channel in prefs["u1"]:
    print(channel, event)
